// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;
    function setUp() public { c = new SimpleWallet(); }

    receive() external payable {}

    function testFuzz_property(address actor, uint256 amount) public {
        vm.assume(actor != address(0) && actor != address(c) && actor != address(this));
        amount = bound(amount, 1, type(uint256).max / 2);

        // deposit through the payable fallback
        vm.deal(actor, amount);
        vm.prank(actor);
        (bool depOk,) = address(c).call{value: amount}("");
        assertTrue(depOk && address(c).balance == amount && c.depositsCount() == 1);

        // owner (this test contract, which can receive ETH) drains the contract
        vm.prank(address(this));
        bool ok;
        try c.withdrawAll() { ok = true; } catch { ok = false; }

        // GENERAL RULE: withdrawAll by the owner always succeeds and empties the contract
        assertTrue(ok && address(c).balance == 0);
    }
}
